    21  static const char *IVF_SIGNATURE = "DKIF";
    22
    23  static void fix_framerate(int *num, int *den) {
    24    if (*den <= 0 || *den >= 1000000000 || *num <= 0 || *num >= 1000) {
    25      // framerate seems to be invalid, just default to 30fps.
    26      *num = 30;
    27      *den = 1;
    28    }
    29  }
